// Precious-metals pages (issues #63 / #66): the overview + one page per metal, generated by scripts/markets/gen-metals.mjs.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { sitemapXml } from '../workers/pbe-predictions/src/pages.js';

const read = (p) => readFileSync(new URL(`../${p}`, import.meta.url), 'utf8');
const PAGES = { '/markets/metals/': [null, 'markets/metals/index.html'], '/commodities/gold/': ['GOLD', 'commodities/gold/index.html'],
  '/commodities/silver/': ['SILVER', 'commodities/silver/index.html'], '/commodities/platinum/': ['PLATINUM', 'commodities/platinum/index.html'] };

test('every metals page: canonical, metal filter, sibling nav, the one shell, the metals/1 controller, indexable', () => {
  for (const [path, [metal, file]] of Object.entries(PAGES)) {
    const html = read(file);
    assert.match(html, new RegExp(`<link rel="canonical" href="https://predictions\\.propbetedge\\.ai${path.replace(/\//g, '\\/')}">`), file);
    if (metal) assert.match(html, new RegExp(`data-metal="${metal}"`), file); else assert.doesNotMatch(html, /data-metal=/, file);
    for (const href of ['/markets/metals/', '/commodities/gold/', '/commodities/silver/', '/commodities/platinum/']) assert.ok(html.includes(`href="${href}"`), `${file} links ${href}`);
    assert.match(html, new RegExp(`href="${path}" aria-current="page"`), `${file} marks itself current`);
    assert.match(html, /<!-- network:header -->[\s\S]*class="topbar"[\s\S]*<!-- \/network:header -->/);
    assert.match(html, /net-footer/);
    assert.match(html, /\/markets\/metals\/metals\.js\?v=/);
    assert.match(html, /<meta name="robots" content="index,follow">/);
    assert.equal(JSON.parse(html.match(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/)[1])['@graph'][0].url, `https://predictions.propbetedge.ai${path}`);
  }
});

test('static HTML carries no price: every number on the page comes from metals/1 at runtime (fees and dates only)', () => {
  for (const [, file] of Object.values(PAGES)) {
    // the page's own content only (the shared shell carries the All Access $29/month line, not a metal price)
    const text = read(file).match(/<main id="main">([\s\S]*?)<\/main>/)[1].replace(/<script[\s\S]*?<\/script>/g, '').replace(/<[^>]+>/g, ' ');
    assert.doesNotMatch(text, /\$\s?\d/, `${file} shows a dollar figure`);
  }
});

test('metal pages describe their own trust; sitemap + trailing-slash redirects cover all three', () => {
  assert.match(read('commodities/gold/index.html'), /GLD[\s\S]*LBMA Gold Price/);
  assert.match(read('commodities/silver/index.html'), /SLV[\s\S]*July 24, 2008/);
  assert.match(read('commodities/platinum/index.html'), /PPLT[\s\S]*May 18, 2026/);
  const sm = sitemapXml([]);
  for (const m of ['gold', 'silver', 'platinum']) assert.ok(sm.includes(`/commodities/${m}/</loc>`), m);
  const redirects = JSON.parse(read('vercel.json')).redirects;
  for (const m of ['gold', 'silver', 'platinum']) assert.ok(redirects.some((r) => r.source === `/commodities/${m}` && r.destination === `/commodities/${m}/` && r.permanent));
});

test('the controller narrows to one metal and links the overview cards to the metal pages', () => {
  const js = read('markets/metals/metals.js');
  assert.match(js, /document\.body\.dataset\.metal/);
  assert.match(js, /filter\(\(x\) => !ONLY \|\| x\.metal === ONLY\)/);
  assert.match(js, /filter\(\(e\) => !ONLY \|\| e\.metal === ONLY\)/);
  assert.match(js, /commodities\/gold\//);
});
